import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.CD2m2Tvf.js";const g=JSON.parse('{"title":"14.1 Requirements & Capacity Estimation","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.1-requirements-and-estimation.md","filePath":"system-design/14.1-requirements-and-estimation.md"}'),s={name:"system-design/14.1-requirements-and-estimation.md"};function o(r,e,l,c,m,u){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="_14-1-requirements-capacity-estimation" tabindex="-1">14.1 Requirements &amp; Capacity Estimation <a class="header-anchor" href="#_14-1-requirements-capacity-estimation" aria-label="Permalink to &quot;14.1 Requirements &amp; Capacity Estimation&quot;">​</a></h1><h2 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h2><ul><li>Ingest OpenTelemetry OTLP Protobuf and JSON span batches over HTTP/gRPC.</li><li>Execute tail-based sampling to retain 100% of error and latency outlier traces while downsampling nominal traces.</li><li>Reconstruct span DAGs on demand and compute the critical execution path.</li><li>Provide sub-second multi-dimensional search over billions of stored spans.</li><li>Run statistical anomaly detection and generate automated LLM incident postmortems.</li></ul><h2 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h2><ul><li><strong>High Ingestion Availability</strong>: 99.99% ingestion uptime; ingestion failure must never crash instrumented upstream services.</li><li><strong>Low Query Latency</strong>: p95 trace retrieval under 500ms for traces containing up to 5,000 spans.</li><li><strong>Data Durability</strong>: Zero telemetry loss during graceful rolling collector restarts.</li></ul><hr><h2 id="capacity-estimation-arithmetic" tabindex="-1">Capacity Estimation Arithmetic <a class="header-anchor" href="#capacity-estimation-arithmetic" aria-label="Permalink to &quot;Capacity Estimation Arithmetic&quot;">​</a></h2><h3 id="ingestion-volume" tabindex="-1">Ingestion Volume <a class="header-anchor" href="#ingestion-volume" aria-label="Permalink to &quot;Ingestion Volume&quot;">​</a></h3><ul><li><strong>Target Scale</strong>: 10,000 requests/second across upstream microservices.</li><li><strong>Spans Per Request</strong>: Average 15 spans generated per distributed transaction.</li><li><strong>Gross Span Ingestion Rate</strong>: $10,000 \\times 15 = 150,000\\text{ spans/second}$.</li></ul><h3 id="data-storage-volume" tabindex="-1">Data Storage Volume <a class="header-anchor" href="#data-storage-volume" aria-label="Permalink to &quot;Data Storage Volume&quot;">​</a></h3><ul><li><strong>Average Uncompressed Span Size</strong>: ~500 bytes (service name, span name, tags, timestamps).</li><li><strong>Gross Ingestion Bandwidth</strong>: $150,000 \\times 500\\text{ bytes} = 75\\text{ MB/second} = 600\\text{ Mbps}$.</li><li><strong>Tail Sampling Reduction</strong>: 90% of healthy nominal traffic is discarded; 10% retained.</li><li><strong>Net Ingestion Rate to Storage</strong>: $15,000\\text{ spans/second} = 7.5\\text{ MB/second}$.</li><li><strong>ClickHouse Columnar Compression</strong>: 6x compression ratio using ZSTD on timestamps and dictionary encoding on strings.</li><li><strong>Net Disk Write Rate</strong>: $\\frac{7.5\\text{ MB/s}}{6} = 1.25\\text{ MB/second} \\approx 108\\text{ GB/day}$.</li><li><strong>30-Day Retention Disk Requirement</strong>: $108\\text{ GB/day} \\times 30\\text{ days} \\approx 3.24\\text{ TB}$ of storage.</li></ul><h3 id="_30-second-spoken-interview-answer" tabindex="-1">30-Second Spoken Interview Answer <a class="header-anchor" href="#_30-second-spoken-interview-answer" aria-label="Permalink to &quot;30-Second Spoken Interview Answer&quot;">​</a></h3><blockquote><p>&quot;When designing capacity for this tracing engine, I modeled 10,000 user requests per second with an average fanout of 15 spans, generating 150,000 spans per second. Rather than storing every nominal span—which would require 6.5 terabytes per day—our tail sampling engine retains 100% of errors and p99 outliers while downsampling nominal traces to 10%. Combined with ClickHouse&#39;s 6x columnar compression, we write just 1.25 megabytes per second to disk, storing 30 days of high-fidelity incident history in under 3.3 terabytes.&quot;</p></blockquote>',13)])])}const p=t(s,[["render",o]]);export{g as __pageData,p as default};
